/**
 * Benchmarks the Bulk (SPARQL) validation of {@code sh:class} when the constrained class has RDFS subclasses - the path
 * changed in {@link org.eclipse.rdf4j.sail.shacl.ast.constraintcomponents.ClassConstraintComponent}.
 *
 * <p>
 * Before the change the generated filter had one {@code EXISTS} per (sub)class:
 *
 * <pre>
 * FILTER(!(EXISTS{?value a &lt;Sub_0&gt;} || EXISTS{?value a &lt;Sub_1&gt;} || ... ))
 * </pre>
 *
 * After the change it is a single {@code EXISTS} with an IN-list, the constrained class first:
 *
 * <pre>
 * FILTER(NOT EXISTS{?value a ?t . FILTER(?t IN (&lt;Part&gt;, &lt;Sub_0&gt;, &lt;Sub_1&gt;, ...))})
 * </pre>
 *
 * <p>
 * {@link #bulkValidation} runs the real ShaclSail Bulk validation over an already-loaded store, so it measures whatever
 * filter the current build of {@code ClassConstraintComponent} generates. Comparing old vs new therefore means running
 * it twice - once on a build without the change and once with it.
 *
 * <p>
 * <b>Engine caveat:</b> the change was motivated by GraphDB, whose engine evaluates every {@code EXISTS} as a per-row
 * sub-query and therefore pays the sub-query setup once per class for every value. The stock RDF4J evaluator
 * short-circuits the {@code ||} chain and its {@code EXISTS} is comparatively cheap, so the gap measured on RDF4J is
 * expected to be smaller (or even reversed for few subclasses). {@link #createBaseSail(File, boolean)} is overridable
 * so the same workload can be run on another store/engine.
 *
 * <p>
 * All data is valid, so the validation sweeps every value instead of stopping early, and every value is typed with a
 * leaf subclass ({@code Sub_(i % subclasses)}) so the old {@code ||} chain hits the matching class at a different
 * position for different values.
 *
 * @author Sava Savov
 */
@State(Scope.Benchmark)
@Warmup(iterations = 5)
@BenchmarkMode(Mode.AverageTime)
@Fork(value = 0, jvmArgs = { "-Xms8G", "-Xmx8G" })
@Measurement(iterations = 10)
@OutputTimeUnit(TimeUnit.MILLISECONDS)
public class ClassConstraintSparqlFilterBenchmark {
	private static final String EX = "http://example.com/ns#";
	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();

	private static final IRI ROOM = VF.createIRI(EX, "Room");
	private static final IRI HAS_PART = VF.createIRI(EX, "hasPart");
	private static final IRI PART = VF.createIRI(EX, "Part");
	// Unrelated to the shapes; re-added by every bulkValidation() so its commit does not change the store.
	private static final Statement MARKER = VF.createStatement(VF.createIRI(EX, "benchmark"), RDF.VALUE,
			VF.createLiteral("marker"));

	/**
	 * Number of direct subclasses of {@code ex:Part}. This is the number of {@code EXISTS} in the old filter (plus one
	 * for {@code ex:Part} itself) and the length of the IN-list in the new one - the main lever of the optimization.
	 */
	@Param({ "5", "25", "100" })
	public int subclasses;

	/**
	 * {@code true}: the base store is wrapped in a {@link SchemaCachingRDFSInferencer}, so every value also has the
	 * materialized type {@code ex:Part} (which the new filter tries first). {@code false}: plain store, values only
	 * carry their leaf type and the subclasses are resolved by the ShaclSail's own {@code RdfsSubClassOfReasoner}.
	 */
	@Param({ "false", "true" })
	public boolean baseInference;

	/**
	 * Number of {@code ex:Room} targets.
	 */
	public int rooms = 20_000;

	/**
	 * Number of {@code ex:hasPart} values per room, i.e. {@code rooms * partsPerRoom} values are checked.
	 */
	public int partsPerRoom = 5;

	private Path dataDir;
	private SailRepository shaclRepository;

	@Setup(Level.Trial)
	public void setUp() throws IOException {
		((Logger) LoggerFactory.getLogger(ShaclSailConnection.class.getName()))
				.setLevel(ch.qos.logback.classic.Level.INFO);

		List<IRI> subclassIris = new ArrayList<>(subclasses);
		for (int i = 0; i < subclasses; i++) {
			subclassIris.add(VF.createIRI(EX, "Sub_" + i));
		}

		dataDir = Files.createTempDirectory("shacl-class-filter-bench");
		NotifyingSail baseSail = createBaseSail(dataDir.toFile(), baseInference);
		ShaclSail sail = new ShaclSail(baseSail);
		sail.setShapesGraphs(Set.of(RDF4J.SHACL_SHAPE_GRAPH));
		sail.setParallelValidation(false);
		sail.setCacheSelectNodes(true);
		sail.setSerializableValidation(false);
		sail.setPerformanceLogging(false);
		shaclRepository = new SailRepository(sail);
		shaclRepository.init();

		try (SailRepositoryConnection connection = shaclRepository.getConnection()) {
			connection.begin(ShaclSail.TransactionSettings.ValidationApproach.Disabled);
			connection.add(new StringReader(shapes()), "", RDFFormat.TURTLE, RDF4J.SHACL_SHAPE_GRAPH);
			connection.add(createData(subclassIris));
			connection.add(MARKER);
			connection.commit();
		}

		// Throws if the data does not conform. With baseInference=false that also proves the subclasses were expanded
		// by the RdfsSubClassOfReasoner, i.e. that the multi-class filter is the one being measured.
		bulkValidation();
	}

	@TearDown(Level.Trial)
	public void tearDown() {
		if (shaclRepository != null) {
			shaclRepository.shutDown();
		}
		deleteRecursively(dataDir);
	}

	/*
	 * --------------- * Benchmarks * --------------- *
	 */

	/**
	 * Real Bulk validation of the whole, already-loaded store. Measures whatever filter the current build generates;
	 * A/B across builds.
	 *
	 * <p>
	 * A Bulk commit validates the entire base sail, so the transaction only re-adds one unrelated, already-present
	 * statement and leaves the store unchanged. {@link ShaclSailConnection#revalidate()} is deliberately not used: it
	 * skips {@code prepareValidation}, so the {@code RdfsSubClassOfReasoner} is {@code null} and {@code sh:class} is
	 * validated against the constrained class alone - the multi-class filter under test would never be generated.
	 */
	@Benchmark
	public void bulkValidation() {
		try (SailRepositoryConnection connection = shaclRepository.getConnection()) {
			connection.begin(ShaclSail.TransactionSettings.ValidationApproach.Bulk);
			connection.add(MARKER);
			connection.commit();
		}
	}

	/*
	 * --------------- * Data * --------------- *
	 */

	private String shapes() {
		return "@prefix ex: <" + EX + "> .\n" +
				"@prefix sh: <http://www.w3.org/ns/shacl#> .\n\n" +
				"ex:RoomShape a sh:NodeShape ;\n" +
				" sh:targetClass ex:Room ;\n" +
				" sh:property [ sh:path ex:hasPart ; sh:class ex:Part ] .\n";
	}

	private List<Statement> createData(List<IRI> subclassIris) {
		List<Statement> statements = new ArrayList<>(subclassIris.size() + rooms * (1 + 2 * partsPerRoom));
		// The ontology lives in the data graph: the ShaclSail's RdfsSubClassOfReasoner reads it from there, and with
		// baseInference=true the RDFS inferencer materializes ex:Part for every value.
		for (IRI subclass : subclassIris) {
			statements.add(VF.createStatement(subclass, RDFS.SUBCLASSOF, PART));
		}
		int value = 0;
		for (int r = 0; r < rooms; r++) {
			// Rooms are typed directly so the target selection stays cheap and the filter dominates.
			IRI room = VF.createIRI(EX, "room_" + r);
			statements.add(VF.createStatement(room, RDF.TYPE, ROOM));
			for (int p = 0; p < partsPerRoom; p++, value++) {
				IRI part = VF.createIRI(EX, "part_" + value);
				statements.add(VF.createStatement(room, HAS_PART, part));
				statements.add(VF.createStatement(part, RDF.TYPE, subclassIris.get(value % subclassIris.size())));
			}
		}
		return statements;
	}

	/*
	 * --------------- * Store * --------------- *
	 */

	/**
	 * The store under test. Override to run the same workload on another store/engine (e.g. GraphDB). When
	 * {@code inference} is true the returned sail must materialize RDFS subclass inference.
	 */
	protected NotifyingSail createBaseSail(File dataDir, boolean inference) {
		NativeStore store = new NativeStore(dataDir);
		store.setDefaultQueryEvaluationMode(QueryEvaluationMode.STRICT);
		return inference ? new SchemaCachingRDFSInferencer(store, true) : store;
	}

	private static void deleteRecursively(Path dir) {
		if (dir == null) {
			return;
		}
		try (Stream<Path> paths = Files.walk(dir)) {
			paths.sorted(Comparator.reverseOrder()).forEach(p -> {
				try {
					Files.deleteIfExists(p);
				} catch (IOException e) {
					throw new UncheckedIOException(e);
				}
			});
		} catch (IOException e) {
			throw new UncheckedIOException(e);
		}
	}
}
